private overlaps(slot: Slot, anotherSlot: Slot): boolean {
  return (
    slot.id !== anotherSlot.id &&
    slot.start < anotherSlot.end &&
    slot.end > anotherSlot.start
  );
}

async getSlots(): Promise<ResourceSlotsDto[]> {
  const [resources, slots, blockingDependencies] = await Promise.all([
    this.manager.find(Resource, { order: { id: 'ASC' } }),
    this.manager.find(Slot, { order: { resourceId: 'ASC', start: 'ASC' } }),
    this.manager.find(BlockingDependency, { order: { id: 'ASC' } }),
  ]);

  const slotsByResource = new Map<number, Slot[]>();
  for (const slot of slots) {
    const resourceSlots = slotsByResource.get(slot.resourceId);
    if (resourceSlots) {
      resourceSlots.push(slot);
    } else {
      slotsByResource.set(slot.resourceId, [slot]);
    }
  }

  const blockedIdsByBlocker = new Map<number, number[]>();
  const blockerIdsByBlocked = new Map<number, number[]>();
  for (const dependency of blockingDependencies) {
    const blockedIds = blockedIdsByBlocker.get(dependency.blockingResourceId);
    if (blockedIds) {
      blockedIds.push(dependency.blockedResourceId);
    } else {
      blockedIdsByBlocker.set(dependency.blockingResourceId, [
        dependency.blockedResourceId,
      ]);
    }

    const blockerIds = blockerIdsByBlocked.get(dependency.blockedResourceId);
    if (blockerIds) {
      blockerIds.push(dependency.blockingResourceId);
    } else {
      blockerIdsByBlocked.set(dependency.blockedResourceId, [
        dependency.blockingResourceId,
      ]);
    }
  }

  const groups = resources.map((resource) => ({
    resourceId: resource.id,
    slots: [] as SlotDto[],
  }));
  const groupsById = new Map(groups.map((group) => [group.resourceId, group]));

  for (const resource of resources) {
    const ownSlots = slotsByResource.get(resource.id) ?? [];
    const blockerIds = blockerIdsByBlocked.get(resource.id) ?? [];
    const candidates = [
      ...ownSlots,
      ...blockerIds.flatMap(
        (blockerId) => slotsByResource.get(blockerId) ?? [],
      ),
    ];
    const ownGroup = groupsById.get(resource.id);
    const blockedGroups = (blockedIdsByBlocker.get(resource.id) ?? [])
      .map((blockedId) => groupsById.get(blockedId))
      .filter((group): group is ResourceSlotsDto => group !== undefined);

    for (const slot of ownSlots) {
      const slotWithConflicts: SlotDto = {
        ...slot,
        conflicts: candidates.filter((other) => this.overlaps(slot, other)),
      };
      ownGroup?.slots.push(slotWithConflicts);
      for (const blockedGroup of blockedGroups) {
        blockedGroup.slots.push(slotWithConflicts);
      }
    }
  }

  return groups;
}

